/* المُلهم، «تعلّم»: مكتبة المؤلفين، كتاب «القواعد العشر» */
window.HH_LIB=window.HH_LIB||{};
window.HH_LIB["ten"]={"id":"ten","title":"القواعد العشر","sub":"أهم القواعد في تربية الأبناء","author":"أ.د. عبدالكريم بكار","coauthors":[],"translator":"","publisher":"مؤسسة الإسلام اليوم، والتنفيذ الفني والنشر والتوزيع: دار وجوه للنشر والتوزيع (الرياض)","year":"1432 ه، 2011","edition":"الطبعة الرابعة","series":"التربية الرشيدة (2)","lead":"كتاب موجز يجمع عشر قواعد مركزية في تربية الأبناء وتهذيبهم، يقول مؤلفه في مقدمته: «فإنه قد انقدح في ذهني أن أتحدث عن المفاتيح المركزية أو الأمهات في التعامل مع الأبناء وتهذيبهم، لعلني أساعد القارئ الكريم على امتلاك الخطوط العريضة جداً في فهم أدبيات تربية الأبناء». واختار العدد عشرة لأنه «رقم مطمئن ومتوسط الحجم»، مع تنبيهه على أن «ما يطرح في شأن تربية الأبناء هو موضع اتفاق في (80 %) منه بين كل الأمم وكل الحضارات».","audience":"الآباء والمربون، وكل من يعنى بتربية الأبناء في الأسرة","bio":"","chapters":[{"k":"c1","t":"القاعدة الأولى: ما قبل الإنجاب","q":"لماذا يحتاج المربي إلى ثقافة تربوية قبل أن يربي؟","essence":"الطفل أعقد من أي آلة فتعلم قبل التربية","kw":["الثقافة التربوية","الصبر","اختلاف الأبناء"],"sections":[{"t":"ما قبل الإنجاب، وما الثقافة التربوية؟","pg":8,"key":"تعني الثقافة التربوية: مجموعة المعلومات والخبرات التي نحتاج إليها في تكوين البيئة التربوية، وفي طرق تهذيب الأبناء وتنشئتهم النشأة الصالحة، وفي التعامل مع مشكلاتهم وأخطائهم.","p":["الطفل أعقد من أي آلة، ويحتاج تربيته التربية الرشيدة إلى معرفة وخبرة وحذق، لكن الناس لا يحبون الاعتراف بذلك","وما ذلك إلا لأنَّ التربية عملية معقدة جداً، وتتطلب قدراً جيداً من المعرفة والحكمة، وقدراً جيداً من الاتزان الانفعالي لدى المربي"],"items":[{"h":"التشبيه بالآلة","x":"من يشتري آلة حديثة يقرأ دليلها أو يسأل من سبقه إلى تشغيلها، والطفل أولى بذلك من أي آلة."},{"h":"ثمار الجهل","x":"يرى المؤلف أن ثمار ترك التثقف تظهر في انحراف أعداد كبيرة من المراهقين والمراهقات، وفشل آخرين في دراستهم وحياتهم العملية."}]},{"t":"التربية ممتعة جداً وشاقة جداً","pg":8,"key":"نعم هذا هو شأن التربية، علينا أن نستمر في العمل ولو لم نر النتائج، ولم نلمس التغيرات، فهي موجودة، وكثيراً ما تظهر فجأة","p":["حيث إنها تظل بعد وضع البذور نحواً من أربع سنوات تضرب بجذورها الليفية في الأرض، ولا يُرى منها سوى برعم صغير ينبت من البصلة، وفي السنة الخامسة يصل ارتفاع الشجرة إلى ثمانين قدماً!"],"items":[{"h":"شجرة البامبو","x":"مثال يضربه المؤلف لثمار التربية التي تتأخر في الظهور ثم تبدو دفعة واحدة."},{"h":"لا يأس","x":"المشقة جزء من متعة التربية، فلا داعي إلى اليأس والقنوط والملل."}]},{"t":"من البيئات الضيقة إلى البيئات الواسعة، وانهيار الأسرة أساس انهيار الحضارة","pg":9,"key":"أن إصلاح الخلل الذي في حياتنا لن يتجه من الخارج إلى الداخل، وإنما من الداخل إلى الخارج.","p":["انهيار الحضارة نابع من انهيار المجتمع، وانهيار المجتمع نابع من تفكك الأسرة؛ لأن الأسرة هي الوحدة الأساسية المكونة للمجتمع"],"items":[{"h":"ضعف التكافل","x":"في البيئات الضيقة كان المجتمع كله يربي، ومع اتساع الخصوصية صار على الآباء أن يتحملوا عبء التربية بمفردهم."},{"h":"أخطر أسباب التفكك","x":"انهيار العقيدة وخمود جذوة الإيمان، وضعف شعور الأبوين بالمسؤولية، والبحث عن الملذات بأساليب منحطة."}]},{"t":"علينا أن نتخذ من الحالات الصعبة مفتاحاً للتثقف","pg":10,"key":"تعاملنا مع الحالات الخاصة والصعبة يشكل اختباراً لنا، وعلينا أن ننجح في ذلك الاختبار.","p":["فإن المطلوب ليس الشكوى، ولكن أن نقرأ حول التعامل مع الطفل العنيد، تماماً كما نقرأ لو كان أحد الأبناء مصاباً بفصام الشخصية، أو بمرض غريب يحتاج إلى عناية خاصة."],"items":[{"h":"الطفل الكسول","x":"على الأسرة أن تقرأ عن التعامل معه، وتتخذ موقفاً موحداً وصارماً من محاولته ترك المدرسة، مع استشارة متخصص ووسائل التشجيع."},{"h":"الصعوبة مصدر إثراء","x":"تصبح الصعوبات التربوية مصدراً لإثراء الثقافة التربوية بدل الاستسلام لها."}]},{"t":"ثقافة تربوية لكل الأسرة، والاختلاف بين الناس هو الأساس","pg":11,"key":"الثقافة التربوية ليست مهمة للأبوين فحسب، إنها مهمة للأسرة كلها، لن يستطيع الأبوان بمفردهما تحمل كل أعباء التربية","p":["لعل من أكبر الأخطاء التي نرتكبها في حياتنا العامة، وفي حياتنا الأسرية: الاعتقاد أن الآخرين يفكرون بنفس طريقتنا"],"items":[{"h":"الأخطاء فرص","x":"رسوب البنت أو مشاجرة الأخوين أو غيبة أحد الناس، كلها مناسبات لإظهار الثقافة العامة للأسرة وتقوية روابطها."},{"h":"لكل ابن أسلوب","x":"ما يصلح في التعامل مع أحد الأبناء قد لا يصلح مع أخيه، والمطلوب تنويع الأساليب وإثراء الثقافة التربوية باستمرار."}]},{"t":"التربية جهد مشكور، وقضاء لدَين","pg":12,"key":"فالمسألة دَيْن ووفاء، وأخذ وعطاء.","p":["بالمعرفة والخبرة والتفاؤل والصبر والمثابرة يمكننا أن نفعل الكثير، وسنفعل؛ بإذن الله تعالى."],"items":[{"h":"جهد مأجور","x":"الجهد في توجيه الأبناء مأجور إن شاء الله، وقد يرفعنا دعاؤهم بعد موتنا."},{"h":"دين نقضيه","x":"ما نبذله لأبنائنا كان مطلوباً من آبائنا تجاهنا، وسيكون مطلوباً من أبنائنا تجاه أبنائهم."}]}],"quiz":[{"q":"ما المقصود بالثقافة التربوية عند المؤلف؟","o":["معلومات وخبرات نحتاجها في تكوين البيئة التربوية وتهذيب الأبناء","شهادات جامعية يحملها الأبوان في علوم التربية وعلم النفس الحديث","حفظ القواعد العامة للتربية من الكتب المؤلفة والمترجمة","خبرة يكتسبها المربي تلقائياً بمرور السنين دون أن يتعلم"],"why":"تعني الثقافة التربوية: مجموعة المعلومات والخبرات التي نحتاج إليها في تكوين البيئة التربوية، وفي طرق تهذيب الأبناء وتنشئتهم النشأة الصالحة","pg":8},{"q":"لماذا ضرب المؤلف مثلاً بشجرة البامبو الصينية؟","o":["لأن ثمار التربية قد تتأخر طويلاً ثم تظهر فجأة","لأن الطفل ينمو أسرع ما يكون في سنواته الخمس الأولى","لأن البيئة الواسعة أخطر على الطفل من البيئة الضيقة","لأن جذور الأسرة الممتدة أقوى من جذور الأسرة الصغيرة"],"why":"علينا أن نستمر في العمل ولو لم نر النتائج، ولم نلمس التغيرات، فهي موجودة، وكثيراً ما تظهر فجأة","pg":8},{"q":"أسرة لديها ولد كسول لا يحب الدراسة، فما الذي يقترحه المؤلف عليها؟","o":["أن تتثقف وتتخذ موقفاً موحداً مع استشارة متخصص","أن تكثر الدعاء له وتنتظر تغيره مع مرور الأيام","أن تنقله إلى مدرسة أخرى أخف في متطلباتها","أن تتركه حتى يكبر فتنتهي مشكلته وحدها"],"why":"عليها أن تقرأ وتتثقف حول التعامل مع الطفل الكسول، وأن تتخذ موقفاً موحداً وصارماً تجاه محاولته ترْك المدرسة، بالإضافة إلى استشارة متخصص","pg":10},{"q":"ما الخطأ الكبير الذي ينبه عليه المؤلف في حياتنا الأسرية؟","o":["ظننا أن غيرنا ينظرون إلى الأمور كما ننظر","إكثارنا من الدعاء للأبناء بالهداية والصلاح","استعانتنا بالأبناء الكبار في تربية الصغار","تحويلنا أخطاء الأبناء إلى مناسبات للحوار"],"why":"لعل من أكبر الأخطاء التي نرتكبها في حياتنا العامة، وفي حياتنا الأسرية: الاعتقاد أن الآخرين يفكرون بنفس طريقتنا","pg":11},{"q":"كيف يصف المؤلف ما يبذله الآباء في تربية أبنائهم؟","o":["دين ووفاء، فقد كان مطلوباً من آبائنا تجاهنا","تفضل منا على الأبناء لا ننتظر منه أي شيء أبداً","واجب يسقط عنا حين يبلغ الأبناء سن الرشد","عبء ثقيل ينبغي أن تحمله المدرسة عنا"],"why":"كان مطلوباً من آبائنا وأمهاتنا تجاهنا، وسيكون مطلوباً من أبنائنا تجاه أبنائهم، فالمسألة دَيْن ووفاء، وأخذ وعطاء.","pg":13}],"scene":{"t":"ابن عنيد","x":"ابنك الأوسط عنيد، ويرفض التوجيه في أكثر المواقف، وقد أرهقك أمره.","opts":["تقرأ عن التعامل مع الطفل العنيد كما تقرأ عن حالة تحتاج عناية خاصة","تكثر الشكوى منه أمام الأقارب لعله يخجل فيتغير","تعامله بالأسلوب نفسه الذي نجح مع أخيه الأكبر"],"why":"فإن المطلوب ليس الشكوى، ولكن أن نقرأ حول التعامل مع الطفل العنيد","pg":10}},{"k":"c2","t":"القاعدة الثانية: نحن جزء من العالم، ولنا خصوصيتنا","q":"كيف نأخذ من التجارب التربوية العالمية دون أن نفقد خصوصيتنا؟","essence":"نحتاج العالم ونحفظ سلم قيمنا","kw":["العولمة","الخصوصية","سلم القيم"],"sections":[{"t":"لماذا نحن جزء من العالم؟","pg":15,"key":"فالتربية في الرؤية الإسلامية ليست من أجل تخريج جيل ناجح وقوي ومؤثر فحسب، وإنما هي في الأساس من أجل تنشئة أبناء مؤمنين صالحين أخيار","p":["العولمة تعولم الأشياء وتعولم الأفكار والتطلعات والأذواق والمعايير، وتعولم أيضاً المشكلات، وأنماط الانحطاط..."],"items":[{"h":"طبيعة بشرية واحدة","x":"ما يدخل السرور على شخص في الصين هو نفسه الذي يدخل السرور على شخص في لبنان أو أمريكا، فحاجات أبنائنا قريبة من حاجات أبناء الناس البعيدين."},{"h":"خبرة الغرب","x":"يملك الغرب خبرات كثيرة على المستوى التربوي، ولديه كم هائل من البحوث والدراسات والإحصاءات."}]},{"t":"الحكمة تكمن دائماً في التواصل مع التمايز","pg":18,"key":"هناك شيء مهم هو أن نلاحظ أننا في حاجة إلى العالم في الوقت الذي نخاف فيه من تأثيراته السلبية فينا، وأعتقد أن هذا ينبغي أن يكون هو موقف كل العقلاء.","p":[],"items":[{"h":"لا نخشى الثقافات الأجنبية","x":"نستفيد مما في الكتب التربوية المترجمة من أفكار وملاحظات ذكية، مع الانتباه لما فيها من خصوصيات ثقافية."},{"h":"التمييز صعب","x":"تمييز الجيد من الرديء في الأفكار التربوية المطروحة عملية صعبة، لكن ليس أمامنا أي خيار."}]},{"t":"شرح خصوصيتنا على الصعيد التربوي","pg":19,"key":"سُلَّم القيم، وإعطاء كل قيمة منزله تليق بها، وهذا يشكل الفارق الأساسي بين أمم الأرض اليوم.","p":["إن هناك مشتركاً ثقافياً بين كل الأمم، وهذا المشترك الثقافي يشكل أكثر من ثمانين في المئة من القيم والأخلاق"],"items":[{"h":"مبادئ نابعة من العقيدة","x":"قيمنا وأخلاقنا نابعة من عقيدتنا، ومن خصوصياتنا العبادات والأحكام الشرعية في الطعام واللباس والعلاقة بين الجنسين."},{"h":"قانون السلم القيمي","x":"حين تتزاحم قيمتان نضحي بالأقل شأناً من أجل الأعظم شأناً، فالنجاح قيمة، وصلاة الفجر قيمة أعظم."},{"h":"النظرة إلى الدنيا","x":"على رأس خصوصياتنا نظرتنا إلى الحياة الدنيا على أنها مزرعة للآخرة."}]},{"t":"نتمتع بتنظير تربوي فريد","pg":20,"key":"إن التنظير التربوي لدى كثير من الأمم يعاني من نوع من الاختناق","p":["المشترَك التربوي بيننا وبين الأمم الأخرى أكثر ما يتجلى في الأساليب والأدوات والإجراءات، وعلينا معاشر المربين أن ننشر الوعي بهذا وذاك."],"items":[{"h":"فراغ الإقناع","x":"يتحدث المؤلف عن عالم الروح والمعنى في التربية الغربية، فيرى فيه عبارات رائقة تفتقر إلى المضمون والإقناع."},{"h":"إهمال الجانب الإيماني","x":"الإلحاد يجعل اهتمام الباحثين منصباً على الجانب العقلي والجسمي مع إهمال الجانب الإيماني والروحي."}]}],"quiz":[{"q":"ما الغاية الأساسية للتربية في الرؤية الإسلامية كما يقرر المؤلف؟","o":["تنشئة أبناء مؤمنين صالحين أخيار","تخريج جيل ناجح وقوي ومؤثر فحسب","إعداد الأبناء للمنافسة في سوق العمل","حماية الأبناء من كل تأثير خارجي"],"why":"وإنما هي في الأساس من أجل تنشئة أبناء مؤمنين صالحين أخيار","pg":15},{"q":"ما الموقف الذي ينبغي أن يقفه العقلاء من العالم في نظر المؤلف؟","o":["نحتاج إليه ونخاف في الوقت نفسه من آثاره السلبية","نأخذ منه كل جديد لأنه سبقنا كثيراً في البحوث والدراسات","ننعزل عنه لأن ثقافته تهدد خصوصيتنا التربوية","نتجاهله لأن مشكلات أطفاله لا تشبه مشكلاتنا"],"why":"أننا في حاجة إلى العالم في الوقت الذي نخاف فيه من تأثيراته السلبية فينا، وأعتقد أن هذا ينبغي أن يكون هو موقف كل العقلاء.","pg":18},{"q":"بحسب المؤلف، ما نسبة المشترك الثقافي بين الأمم من القيم والأخلاق؟","o":["أكثر من ثمانين في المئة","نحو خمسين في المئة تقريباً","أقل من ثلاثين في المئة","أكثر من تسعين في المئة"],"why":"وهذا المشترك الثقافي يشكل أكثر من ثمانين في المئة من القيم والأخلاق","pg":19},{"q":"طالب يسهر للمذاكرة في ليالي الاختبارات فتفوته صلاة الفجر، كيف يحكم المؤلف على ذلك؟","o":["السهر للنجاح ينبغي أن يتم مع التمكن من أداء الفجر","لا حرج فيه لأن النجاح الدراسي قيمة عظيمة تستحق التضحية","يترك تقديره للطالب لأنه أعرف الناس بمصلحته","يمنع السهر في كل الأحوال حتى لو صلى الفجر"],"why":"فإن أي سهر من أجل النجاح ينبغي أن يتم في إطار التمكن من أداء صلاة الفجر في وقتها.","pg":20},{"q":"في أي جانب يتجلى المشترك التربوي بيننا وبين الأمم الأخرى أكثر من غيره؟","o":["في الأساليب والأدوات والإجراءات","في الأهداف والمبادئ والقيم العليا","في ترتيب القيم داخل السلم القيمي","في النظرة إلى الدنيا والآخرة معاً"],"why":"المشترَك التربوي بيننا وبين الأمم الأخرى أكثر ما يتجلى في الأساليب والأدوات والإجراءات","pg":22}],"scene":{"t":"قبول للدراسة في الخارج","x":"حصل ابنك على قبول للدراسة في الخارج، ويغلب على ظنك أن سفره سيؤثر في تدينه.","opts":["تتوقف عن إرساله لأن الاستقامة قيمة أعظم من السفر لطلب العلم","ترسله فوراً لأن طلب العلم قيمة عظيمة لا تفوت","تترك القرار له وحده دون أي نقاش أو توجيه"],"why":"السفر لطلب العلم قيمة عظيمة، ولكن الاستقامة على أمر الله قيمة أعظم، فإذا غلب على الظن أن سفر أحد الأولاد للدراسة سيؤثر في تدينه، فإننا نتوقف عن إرساله","pg":20}},{"k":"c3","t":"القاعدة الثالثة: هل البيئة هي كل شيء؟","q":"ما مكونات البيئة الأسرية التي تصنع الطفل؟","essence":"البيت الجيد يصنعه كبار جيدون","kw":["البيئة الأسرية","القدوة","المكان"],"sections":[{"t":"هل البيئة هي كل شيء؟","pg":23,"key":"تتكون بيئة الأسرة من العديد من العناصر، أهمها: شخصيات أفراد الأسرة، والقيم التي يحملونها، ونوعية العلاقات القائمة بينهم","p":["فتكامل الأبوين والتفاعل بينهما وإشرافهما المباشر على تربية الأبناء، أمور أساسية في تكوين البيئة المطلوبة."],"items":[{"h":"أثر البيئة","x":"يستدل المؤلف بأن أكثر من 99% ممن ينشؤون في مجتمع مسلم يكونون مسلمين، وكذلك في المجتمعات الأخرى."},{"h":"دراسات","x":"قيام الأم وحدها بالتنشئة ينعكس سلباً على الطفل، والأطفال الذين يشترك في تربيتهم الأبوان يتمتعون بقدرات أفضل في القراءة والكتابة والحساب."},{"h":"الحنان يحمي","x":"الجو العائلي الذي يفتقر إلى الرقة والحنان والطمأنينة يدفع المراهقين إلى البحث عن ذلك عند أقرانهم."}]},{"t":"أبوان جيدان","pg":26,"key":"إن التربية سهلة ومثمرة وناجحة إذا كنا نحن الكبار أشخاصاً جيدين","p":["إننا فعلاً نرسم من خلال سلوكنا اليومي مستقبل سلوك أبنائنا","إن الأمة الفقيرة ليست هي التي لا تملك الكثير من المال، لكنها تلك التي يتلفت أطفالها يمنة ويسرة؛ فلا يرون إلا النماذج الباهتة"],"items":[{"h":"الفجوة بين القول والفعل","x":"إذا طالبنا الأبناء بفضائل لا نلتزم بها كانت تربيتنا صعبة وعقيمة ومخيبة للآمال."},{"h":"النموذج المماثل","x":"أقوى نموذج يؤثر في الطفل هو الوالد من الجنس نفسه، فالذكور يتأثرون بآبائهم والبنات بأمهاتهن."},{"h":"القيم لا تفرض","x":"السبيل إلى نقل القيم أن نجذب الأبناء إلينا، وأن يروا في أفعالنا صدقنا ومصداقيتنا."}]},{"t":"بيئة مرحة ومريحة وهادئة","pg":29,"key":"نحن مطالبون بأن نوفر البيئة التي تساعد الطفل على الاحتفاظ بأكبر قدر ممكن من المعاني الرائعة","p":[],"items":[{"h":"الثقة وحسن النية","x":"التعامل مع الطفل على أنه صادق وموثوق وطيب، في بيت يسوده الهدوء والسلام والأمن."},{"h":"المرح والتقليل من النقد","x":"قدر حسن من المزاح والتفاؤل، والتقليل من النقد في البيت ومن خارجه قدر الإمكان."},{"h":"العدل والاعتذار","x":"مراعاة الفروق الفردية، وترك المقارنة السلبية، والاعتذار عند وقوع الخطأ من الكبار أو الصغار، وغض الطرف عن بعض الهفوات."}]},{"t":"المكان يصنع المشاعر","pg":30,"key":"تأثير المكان في الإنسان كبير جداً، وإننا في البداية نقوم بهندسة منازلنا، ثم تقوم مساكننا بهندسة مشاعرنا","p":[],"items":[{"h":"السعة والنظام","x":"الناس في المكان الواسع الجميل المنظم تتولد لديهم مشاعر الرضا والثقة، وفي المكان الضيق الفوضوي تتولد مشاعر الضيق."},{"h":"النظافة والتنسيق","x":"يمكن جعل البيت روضة غناء بالنظافة والتنظيم مهما كانت أحوال الأسرة ضيقة، ليكون مكاناً للوئام والراحة."}]}],"quiz":[{"q":"ما أكثر البيئات تأثيراً في حياة الأطفال كما يرى المؤلف؟","o":["بيئة الأسرة داخل المنزل","بيئة المدرسة والمعلمين","بيئة الشارع والحي والرفاق","بيئة الإعلام والفضائيات"],"why":"لكن ما أقصده هنا تحديداً هو بيئة الأسرة داخل المنزل؛ فهي في الحقيقة الأكثر تأثيراً في حياة الأطفال.","pg":23},{"q":"ماذا أوضحت الدراسة التي ذكرها المؤلف عن قيام الأم وحدها بالتنشئة؟","o":["أنه ينعكس سلباً على شخصية الطفل لعدم توازنها","أنه يجعل الطفل أكثر تفوقاً في القراءة والكتابة","أنه يمنح الطفل استقلالاً مبكراً وثقة بنفسه","أنه لا يختلف في أثره عن مشاركة الأبوين معاً"],"why":"وأوضحت النتائج أن ذلك ينعكس بالسلب على شخصية الطفل بسبب عدم توازنها","pg":24},{"q":"متى تكون التربية سهلة ومثمرة كما يقرر المؤلف؟","o":["إذا كنا نحن الكبار أشخاصاً جيدين","إذا أكثرنا من وعظ الصغار وإرشادهم","إذا وفرنا للأبناء كل ما يطلبونه","إذا أخفينا أخطاءنا عن أعين الصغار"],"why":"إن التربية سهلة ومثمرة وناجحة إذا كنا نحن الكبار أشخاصاً جيدين","pg":26},{"q":"ما الأمة الفقيرة في نظر المؤلف؟","o":["التي لا يرى أطفالها حولهم إلا النماذج الباهتة","التي لا تملك الكثير من المال والموارد","التي يقل فيها عدد المدارس والجامعات","التي يسكن أطفالها في بيوت متواضعة ضيقة وصغيرة"],"why":"إن الأمة الفقيرة ليست هي التي لا تملك الكثير من المال، لكنها تلك التي يتلفت أطفالها يمنة ويسرة؛ فلا يرون إلا النماذج الباهتة","pg":28},{"q":"أخطأ الأب في حق ابنه أمام الأسرة، فأي تصرف يعده المؤلف من مكونات البيئة المريحة؟","o":["أن يعتذر سواء صدر الخطأ من كبير أو صغير","أن يلزم الصغير وحده بالاعتذار حفظاً للهيبة","أن يتجاهل الموقف كله حتى ينساه الجميع","أن يذكر أخطاء الابن السابقة ليتوازن الأمر"],"why":"الاعتذار عند وقوع الخطأ، سواء أكان ذلك من الكبار أم الصغار.","pg":30}],"scene":{"t":"شيخ في الطريق","x":"تقود سيارتك ومعك ابنك، فترى رجلاً كبيراً يعبر الشارع ببطء والسيارات تمر مسرعة من حوله.","opts":["توقف سيارتك وتنزل فتأخذ بيده حتى يعبر الطريق","تطلق البوق لينتبه الرجل ويسرع في العبور","تشرح لابنك فضل مساعدة الكبار وتكمل طريقك"],"why":"إنني أشعر أنني تعلمت من أبي درساً في المبادرة والشهامة قد لا أتعلمه إذا قرأت في ذلك كتاباً مؤلفاً من ثلاثمائة صفحة.","pg":28}},{"k":"c4","t":"القاعدة الرابعة: التربية تفاعل","q":"كيف يتحول اجتماع الأسرة إلى تفاعل حقيقي يؤثر في الأبناء؟","essence":"لا تأثير بلا تفاعل في الاتجاهين","kw":["التفاعل","الأسئلة","التلفاز"],"sections":[{"t":"التربية تفاعل","pg":33,"key":"يحصل التأثير والتغيير حين يحدث التفاعل، وكما هو معروف؛ فقد يحصل اختلاط وتقارب دون أن يحدث تفاعل","p":["إن التربية ليست عبارة عن استجابات تصدر من الأطفال لتوجيهات آبائهم أو وصاياهم، وإنما هي عمل في اتجاهين"],"items":[{"h":"حب التساؤل","x":"الأطفال يشعرون أنهم لا يعرفون شيئاً عما حولهم، فيندفعون إلى التعلم، وابن الثالثة يوجه عشرات الأسئلة كل يوم."},{"h":"الكبار يتعلمون أيضاً","x":"الآباء مطالبون بالتفاعل مع أبنائهم، يستمعون إليهم ويستفيدون من ملاحظاتهم ويغيرون في أسلوب تربيتهم."}]},{"t":"كيف نساعد الطفل على التفاعل؟","pg":34,"key":"من القواعد الفكرية المقررة: أن الشيء هبة علاقاته","p":["أجب على تساؤلاته؛ لأنه يتعلم منها الكثير"],"items":[{"h":"الحديث عن الطموحات","x":"الحديث مع الأبناء عن تطلعاتهم وأحلامهم يتيح لهم الفرصة كي يصوغوها في طرح منطقي، ويفتح قناة للتفاعل."},{"h":"قرارات صغيرة","x":"إشراك الأبناء في قرارات يومية مثل وقت وضع المائدة والخروج للنزهة وتوزيع المهام."},{"h":"حدود الكتمان","x":"ليس من المصلحة إطلاع الصغار على كل شيء، لكن لا ينبغي أن يشعروا بالخوف من السؤال عما يؤثر في حياتهم."}]},{"t":"مع أي شيء يتفاعل الأطفال؟","pg":36,"key":"إن كثرة الوعظ للأبناء وكثرة إرشادهم ليست صحيحة، بل تدل على وجود مشكلة حقيقية، هي انعدام أو ضعف التفاعل الأسري.","p":["وذلك لأن الأولاد لا يتفاعلون مع ما لدى والدتهم من أفكار ومفاهيم ومقولات تربوية، وإنما يتفاعلون مع المكونات التي جعلت منها شخصية مستقلة، وصاحبة مسؤولية."],"items":[{"h":"الأفعال قبل الأقوال","x":"الأطفال يتفاعلون مع ما لدى الكبار من مشاعر واتجاهات وما يشاهدونه من أعمالهم وسلوكاتهم ومواقفهم."},{"h":"التناقض يهدم","x":"طفل تنهاه أمه عن الكذب وهو يسمعها تكذب، لن يستجيب لنهيها."}]},{"t":"أمور تجعل التفاعل ضعيفاً","pg":37,"key":"إن مثل هذه التصرفات من الأبوين تجعل العلاقة بينهم وبين أبنائهم علاقة خصوم ومتحاربين، وليست علاقة رحمة ووئام واحترام وتفاهم","p":[],"items":[{"h":"فجوة الأجيال","x":"الجيل الجديد يميل أكثر إلى التحرر من القيود والتقاليد، وكثير من المشاكسات مع المراهقين تنتهي بعد مدة حين يشبون عن الطوق."},{"h":"الثقة الزائدة","x":"بعض المربين يظهرون كأنهم دائماً على حق، فلا يتيحون للأبناء فرصة للمراجعة أو المحاورة."},{"h":"التطرف في التأديب","x":"مثل الإسراف في العقاب البدني، ومقارنة الصغير بأبناء الأقارب، والصراخ السريع، والإفراط في التوجيه، وتوجيه أصابع الاتهام."},{"h":"التلفاز","x":"شجع على العزلة الاجتماعية والترفيه المستقل، فلا بد من تقليل مشاهدته وتحديد أوقات لا يفتح فيها."}]}],"quiz":[{"q":"متى يحصل التأثير والتغيير في التربية بحسب المؤلف؟","o":["حين يحدث التفاعل بين الكبار والصغار","حين يجتمع أفراد الأسرة كلهم في مكان واحد","حين يكثر الآباء من التوجيه والنصح","حين يطيع الأطفال الأوامر دون نقاش"],"why":"يحصل التأثير والتغيير حين يحدث التفاعل، وكما هو معروف؛ فقد يحصل اختلاط وتقارب دون أن يحدث تفاعل","pg":33},{"q":"سألك ابنك سؤالاً وأنت مشغول جداً، فما التصرف الذي يقترحه المؤلف؟","o":["تقول: لا أستطيع الآن، وعلى العشاء اسأل عما تشاء","تنهره حتى يتعلم ألا يسأل أبداً في وقت غير مناسب","تتجاهل سؤاله حتى ينساه أو يذهب فيسأل غيرك","تجيبه بأي جواب سريع حتى يتركك تكمل عملك"],"why":"وإذا سأل في وقت غير مناسب، فقل له: الآن لا أستطيع أن أتحدث معك، وإذا كنا على مائدة العشاء، فسيكون في إمكانك السؤال عن أي شيء.","pg":35},{"q":"على أي شيء تدل كثرة الوعظ والإرشاد للأبناء في نظر المؤلف؟","o":["على ضعف التفاعل الأسري أو انعدامه","على حرص الأبوين وشدة اهتمامهما","على عناد الأبناء وقلة استجابتهم للنصح","على تأثر الأبناء بالإعلام والرفاق"],"why":"بل تدل على وجود مشكلة حقيقية، هي انعدام أو ضعف التفاعل الأسري.","pg":36},{"q":"لماذا قد تنجح أم لا تحمل إلا شهادة الثانوية أكثر من أم تحمل البكالوريوس في التربية؟","o":["لأن الأولاد يتأثرون بشخصيتها لا بمقولاتها","لأن الشهادة الجامعية تشغل الأم عن أبنائها كثيراً","لأن الأم الأقل تعليماً أكثر صرامة في الضبط","لأن الأولاد يملون من الأم الكثيرة النصح والكلام"],"why":"وذلك لأن الأولاد لا يتفاعلون مع ما لدى والدتهم من أفكار ومفاهيم ومقولات تربوية، وإنما يتفاعلون مع المكونات التي جعلت منها شخصية مستقلة، وصاحبة مسؤولية.","pg":37},{"q":"أي هذه التصرفات يذكره المؤلف بين ما يضعف التفاعل مع الأبناء؟","o":["مقارنة الصغير بأبناء الأقارب لإظهار تقصيره","إشراك الأبناء في القرارات اليومية الصغيرة","الحديث معهم عن تطلعاتهم وأحلامهم وطموحاتهم","إجابة تساؤلاتهم في وقت مناسب لاحق"],"why":"مقارنة الصغير بغيره من أبناء الأقارب من أجل إظهار قصوره وتقصيره.","pg":39}],"scene":{"t":"سؤال صعب","x":"سألك ابنك فجأة: لماذا يكذب بعض الناس؟ وأنت لم تحضر جواباً.","opts":["تثني على سؤاله ثم تطلب رأيه أولاً فيما يسأل عنه","تنهاه عن مثل هذا السؤال لأنه لا يناسب سنه","تجيبه جواباً طويلاً مفصلاً في الحال"],"why":"فقل له: هذا سؤال مهم، وقبل أن أجيبك أريد منك أن تقول لي أنت: لماذا يفعلون ذلك","pg":35},"rel":[{"b":"fam","ci":1,"t":"لماذا يجب أن نتحاور؟"}]},{"k":"c5","t":"القاعدة الخامسة: تربية قائمة على الوضوح","q":"ماذا يجب أن يكون واضحاً في الأسرة حتى تنجح التربية؟","essence":"اعرف أين تقف وماذا تريد وكيف","kw":["الوضوح","الرسائل المحددة","القيم"],"sections":[{"t":"تربية قائمة على الوضوح","pg":41,"key":"يمكن القول: إن (الوضوح) يشكل واحدة من أكبر فضائل الحياة؛ لأنه يتصل بالبصر والبصيرة، والعلم والنور، والوعي والفهم","p":["ولعلي أسلط الضوء هنا على الوضوح في أمور ثلاثة: واقع الأسرة التربوي والعام، والأسلوب الأمثل لتعاملها مع أبنائها، والقيم والأخلاق والمعاني التي تحب أن تربي أبناءها عليها."],"items":[{"h":"الأسرة الواعية","x":"الأسرة الناجحة واعية بأوضاعها وبأهدافها وبالوضعية التي تريد لأطفالها أن يكونوا فيها."}]},{"t":"وضوح الوضع الحالي للأسرة","pg":42,"key":"إن الوعي بالحالة الحاضرة شرط مهم لصواب الخطوة الجديدة التي علينا أن نخطوها، إننا إن لم نعرف أين نقف؛ فسوف يكون من العسير علينا أن نحدد: (إلى أين نتجه؟).","p":[],"items":[{"h":"تفاهم الزوجين","x":"التفاهم على الأسلوب التربوي ضروري، حتى لا ينشق صف الأبوين أمام الأطفال."},{"h":"أسئلة المراجعة","x":"هل الأسرة ملتزمة متدينة؟ هل الجو الأسري صحي ومريح وإيجابي؟ وهل يشعر الأطفال بالأمان والثقة؟"},{"h":"استبيان الأسرة","x":"أب وزع على أسرته استبياناً يسأل عن مواصفات الأسرة الجيدة وما ينقص أسرتهم، فكان ذلك بداية مرحلة جديدة."}]},{"t":"وضوح ما ينبغي عمله، وكيف يعمل","pg":44,"key":"وأعتقد أن نجاح كثير من الآباء والأمهات في تربية أبنائهم يعود إلى أنهم استطاعوا إيصال رسائل محددة وواضحة لأبنائهم حول ما يريدونه منهم","p":["أن التربية ليست عبارة عن متابعة مستمرة للصغار، وليست عبارة عن حشرهم في الزاوية الضيقة، وإملاء التعليمات عليهم"],"items":[{"h":"التخطيط للحديث","x":"من يريد أن يتحدث مع ولده في موضوع فليخطط له، ويتخيل ردود فعله، ويختار الوقت المناسب."},{"h":"رسالة واحدة","x":"تجنب الرسائل الطويلة الغامضة، واطلب من الطفل في المرة الواحدة شيئاً واحداً واشرحه."},{"h":"الدقة مع المراهق","x":"الخطاب مع المراهقين يحتاج إلى حذر وتحديد أكثر، لأنهم يعثرون على الثغرات في الكلام."},{"h":"قوانين وعقود","x":"قوانين قليلة واضحة في البيت، وعقود مكتوبة يرضاها الطرفان تحدد الجزاء والعقوبة."},{"h":"مساحة للاجتهاد","x":"اسأل وناقش وتابع، ولكن اترك له القرار."}]},{"t":"ما نحب أن يكون أبناؤنا عليه","pg":48,"key":"والافتقار إلى تقدير الذات هو أصل كثير من الأمراض الشخصية والاجتماعية.","p":["إن العلاقة بين كسب المال والعمل الجاد علاقة غامضة في أذهان الأطفال، ويجب أن نوضحها لهم."],"items":[{"h":"الصلاح أولاً","x":"نرجو أن يكون أولادنا رجالاً صالحين ونساءً صالحات، ونجعل من أنفسنا قدوات لهم في ذلك."},{"h":"الاعتزاز بالذات","x":"أن يشعروا بكيانات جديرة ومحترمة، فاحترام الناس لهم نتيجة طبيعية لما يملكون من صلاح وكفاءة."},{"h":"الصدق والشجاعة","x":"نرسخ الصدق بالأسئلة والمواقف، والشجاعة الأدبية تعني قول الحق ومقاومة ضغوط الرفاق."},{"h":"الخير والمال","x":"ترسيخ العطاء ومساعدة الآخرين، وتوضيح العلاقة بين المال والعمل، والتشجيع على الادخار."}]}],"quiz":[{"q":"ما الأمور الثلاثة التي يسلط المؤلف عليها ضوء الوضوح؟","o":["واقع الأسرة، والأسلوب الأمثل، والقيم المرجوة","دخل الأسرة، ومدرسة الأبناء، وصلة الأقارب","قوانين البيت، والعقوبات المحددة، والمكافآت المالية","أهداف الأب، وأهداف الأم، ورغبات الأبناء"],"why":"ولعلي أسلط الضوء هنا على الوضوح في أمور ثلاثة: واقع الأسرة التربوي والعام، والأسلوب الأمثل لتعاملها مع أبنائها، والقيم والأخلاق والمعاني التي تحب أن تربي أبناءها عليها.","pg":41},{"q":"لماذا يؤكد المؤلف أهمية الوعي بالحالة الحاضرة للأسرة؟","o":["لأننا إن جهلنا موقعنا عسر علينا تحديد وجهتنا","لأن مقارنة أسرتنا بالأسر الأخرى تحفزنا على التقدم","لأن الأبناء يحبون الحديث عن ماضي أسرتهم","لأن معرفة الأخطاء تكفي وحدها لإصلاحها"],"why":"إننا إن لم نعرف أين نقف؛ فسوف يكون من العسير علينا أن نحدد: (إلى أين نتجه؟).","pg":44},{"q":"قال أب لابنه الصغير: أريد منك أن تكون عطوفاً ومهذباً ومجتهداً. ما ملاحظة المؤلف؟","o":["رسالة طويلة غامضة، والأفضل طلب أمر واحد مع شرحه","رسالة ممتازة لأنها تجمع أهم الصفات المطلوبة في جملة","رسالة مناسبة لكنها تحتاج إلى مكافأة تصحبها","رسالة صحيحة إن قالها أمام إخوته جميعاً"],"why":"هذه رسالة طويلة جداً وغامضة، فالطفل قد لا يفهم معنى: (عطوفاً)، ولا معنى: (مهذباً)، اطلب من الطفل في المرة الواحدة شيئاً واحداً","pg":46},{"q":"ما الصياغة الواضحة التي يقترحها المؤلف مع الفتى الذي يتأخر ليلاً؟","o":["أسمح لك بشرط العودة قبل الثامنة، وإلا مُنعت هذا الشهر","لا بأس بالخروج مع أصدقائك الليلة، بشرط ألا تتأخر كثيراً","اخرج متى شئت، فأنت كبير الآن وتعرف مصلحتك جيداً","لن تخرج مع أصدقائك أبداً طوال أيام الإجازة الصيفية"],"why":"أسمح لك بالذهاب بشرط أن تعود إلى المنزل قبل الساعة الثامنة، وإذا تأخرت عن هذا الموعد؛ فلن أسمح لك بالذهاب مع أصدقائك خلال هذا الشهر","pg":46},{"q":"ما الأساس في غرس الأخلاق والقيم في نفوس الأبناء عند المؤلف؟","o":["الإقناع والاقتناع مع التذكير بالقيم بطرق متنوعة","الضغط والإكراه حتى تصير الأخلاق عادة ثابتة","كتابة القوانين على لوحات وتعليقها في المنزل","المتابعة الدائمة للصغار وإملاء التعليمات المفصلة عليهم"],"why":"ولهذا فإن الإقناع والاقتناع هو الأساس، والضغط يجب أن يتجلى في التذكير بالقيم الفاضلة بطرق مختلفة","pg":50}],"scene":{"t":"اتفاق يتكرر خرقه","x":"اتفقت مع ابنك على المذاكرة ساعتين كل مساء، ثم بدأ يتهرب ويقول إنه لا يذكر ما اتفقتما عليه.","opts":["تكتب الاتفاق في عقد بنسختين يتضمن الجزاء، وتذكّره به عند كل خرق","تعاقبه فوراً بالحرمان دون أي حديث معه","تتنازل عن الاتفاق حتى لا يتوتر جو البيت"],"why":"وكلما حدث خرق لهذا الاتفاق من قبل البنت أخرجت الأم نسخة العقد التي معها، وقالت للبنت: انظري كيف تخرقين ما اتفقنا عليه مرة بعد مرة","pg":47}},{"k":"c6","t":"القاعدة السادسة: التربية اهتمام","q":"ماذا يعني أن نهتم بأبنائنا في عالم متغير؟","essence":"لا تربية من غير اهتمام وقرب","kw":["الاهتمام","القرب","الجلسة الخاصة"],"sections":[{"t":"التربية اهتمام: عالم متغير","pg":55,"key":"فإننا لا نكون مبالغين إذا قلنا: إن التربية اهتمام؛ لأنه فعلاً لا تربية من غير اهتمام.","p":["ونحن نعرف من تجاربنا الشخصية: أن المسائل المعقدة تذلَّل وتصبح سهلة حين نهتم بها، ونعرف أن الأمور اليسيرة والسهلة تصبح صعبة وخطرة من خلال إهمالها والتواني في معالجتها"],"items":[{"h":"حضارة تستبدل القيم","x":"نعيش في ظل حضارة تؤكد على الجمال والقوة والإغراء والمتعة والأنانية، وتحاول إحلالها محل الفضيلة والتواضع."},{"h":"جيل التلفاز","x":"جيل لا يرى من الفضائيات إلا القليل من الدعوة إلى المثل العليا والأخلاق الحميدة."},{"h":"بيئات العزلة","x":"العولمة تصوغ بيئات ثقافية يتراجع فيها التواصل والتراحم والجيرة، وتتقدم مسرات العزلة خلف الأبواب المغلقة."}]},{"t":"الوعي بمسار الأسرة","pg":57,"key":"إن جزءاً كبيراً من اهتمامنا ووعينا ومتابعتنا ينبغي أن ينصب على إدراك المسار الذي تمضي فيه أسرنا من خلال طرح بعض الأسئلة المهمة، ومحاولة الإجابة عليها","p":[],"items":[{"h":"أسئلة المسار","x":"هل لأسرتنا مسار واضح يتفق عليه الجميع؟ هل التعبد والتمسك بالسنن يتقدم أم يتراجع؟ هل التفوق الدراسي هدف حاضر؟ هل التماسك يزداد؟"},{"h":"الخطوة الثانية","x":"جمع الإجابات والتأمل فيها، ثم مناقشتها مع من يمكن من الأبناء للخروج بأفكار تجدد مسار الأسرة."}]},{"t":"كن قريباً","pg":58,"key":"إذا لم يعن الاهتمام بتربية الأبناء القربَ منهم، والحرص على تفهم مشاعرهم ومشكلاتهم؛ فإنه في الحقيقة لا يعني أي شيء.","p":["القرب من الأبناء يعني: بناء علاقة ثقة ومودة معهم، وهذه العلاقة يتم بناؤها عن طريق التحدث معهم في كل الأمور التي تعنيهم مهما كانت صغيرة وغير مهمة","إن علينا أن نقاوم دائماً ما يمكن أن نقع فيه دون أن نشعر من المبالغة في النصح والتحذير والتهديد وإثارة المخاوف."],"items":[{"h":"حاجة المراهق","x":"الصغار يحتاجون إلى من يبتسم في وجوههم، وحين يدخلون طور المراهقة يحتاجون إلى جلسات طويلة وعناية مركزة."},{"h":"نضج متأخر","x":"عقول الأطفال لا تنضج نضوجاً كاملاً إلا في المراهقة المتأخرة، وجزء المخ الخاص بالقرار يكتمل أخيراً."},{"h":"الجلسة الخاصة","x":"كل ابن يحتاج إلى جلسة خاصة مع والده، يتحدث فيها بصدق وصراحة عن الأسرة والدراسة والتدين والقلق والطموح."},{"h":"الحاضر الغائب","x":"من شغلوا بتأمين لقمة العيش أو بأنفسهم، فلم يجدوا الوقت للتواصل، يفاجؤون كثيراً بفشل أبنائهم أو انحرافهم."}]}],"quiz":[{"q":"ما الذي يجعل المسائل المعقدة سهلة في تجربتنا الشخصية كما يرى المؤلف؟","o":["الاهتمام بها، بينما يجعل الإهمال اليسير خطراً","تأجيلها حتى يكبر الأبناء ويفهموا الأمور بأنفسهم","إسنادها إلى المدرسة والمتخصصين وحدهم","تجاهلها لأنها تنتهي تلقائياً مع الوقت"],"why":"أن المسائل المعقدة تذلَّل وتصبح سهلة حين نهتم بها، ونعرف أن الأمور اليسيرة والسهلة تصبح صعبة وخطرة من خلال إهمالها","pg":55},{"q":"بأي اسم يسمي المؤلف الجيل الذي لا يرى إلا القليل من الدعوة إلى المثل العليا؟","o":["جيل التلفاز","جيل العولمة","جيل الإنترنت","جيل المدينة"],"why":"إن لدينا جيلاً جديداً يمكن أن نسميه: (جيل التلفاز)، جيل لا يرى من الفضائيات إلا القليل من الدعوة إلى المثل العليا","pg":56},{"q":"متى يفقد الاهتمام بتربية الأبناء معناه في نظر المؤلف؟","o":["إذا خلا من القرب منهم وتفهم مشاعرهم","إذا لم يصحبه إنفاق سخي على كل حاجاتهم","إذا لم يتضمن متابعة يومية لدرجاتهم","إذا لم يشمل الأقارب والجيران أيضاً"],"why":"إذا لم يعن الاهتمام بتربية الأبناء القربَ منهم، والحرص على تفهم مشاعرهم ومشكلاتهم؛ فإنه في الحقيقة لا يعني أي شيء.","pg":58},{"q":"بماذا يفسر المؤلف ميل سلوك المراهقين إلى العنف والتخبط؟","o":["بأن جزء المخ الخاص باتخاذ القرار يكتمل متأخراً","بأن الآباء يقضون معهم جلسات خاصة طويلة","بأن المدرسة تهمل تعليمهم الأخلاق الحميدة والآداب","بأن رفاقهم يحرضونهم دائماً على آبائهم"],"why":"وإن جزء المخ الذي يُملأ أخيراً هو الجزء الذي يقوم باتخاذ القرار، ويتحكم بالمشاعر، وهو ما يفسر احتمالات ميل سلوك المراهقين إلى العنف والتخبط.","pg":59},{"q":"ما الذي ينبغي أن يقاومه الأب في جلسات المصارحة مع ابنه؟","o":["المبالغة في النصح والتحذير وإثارة المخاوف","روح المرح والطرفة والبساطة في الحديث","الحديث عن طموحات الابن وآماله في المستقبل","سؤال الابن عن نظرته إلى وضع الأسرة"],"why":"إن علينا أن نقاوم دائماً ما يمكن أن نقع فيه دون أن نشعر من المبالغة في النصح والتحذير والتهديد وإثارة المخاوف.","pg":60}],"scene":{"t":"صمت بعد إخفاق","x":"لاحظت أن ابنك المراهق صار صامتاً منذ إخفاقه في أحد الاختبارات، ولا يشكو شيئاً.","opts":["تقترب منه وتعقد معه جلسة خاصة يسودها الصدق والبساطة","تتركه لأن المراهقين يتجاوزون مشكلاتهم وحدهم","تحذره من عواقب الإخفاق وتهدده بالحرمان"],"why":"كل واحد من الأبناء يحتاج إلى جلسة خاصة مع والده بين الفينة والفينة","pg":59}},{"k":"c7","t":"القاعدة السابعة: تربية تقوم على التوازن","q":"كيف يجمع المربي بين الحزم واللين والحرية والضبط؟","essence":"الفضيلة وسط بين إفراط وتفريط","kw":["التوازن","الحرية والضبط","الاختيار"],"sections":[{"t":"تربية تقوم على التوازن","pg":61,"key":"نحن نعرف في مجال الأخلاق والعادات أن الفضيلة وسط بين رذيلتين، أي أن الفضيلة لها طرفان، وكل طرف متصل برذيلة من الرذائل","p":["إذن نحن هنا سنتحدث عن مسألة التوازن في التربية من أجل الاقتراب منها، وليس من أجل حسمها، أو قول الكلمة الفاصلة فيها."],"items":[{"h":"التوازن صعب","x":"يحتاج إلى معرفة ما نريده من الطفل، والمحافظة على شخصيته، والجمع بين مصلحته وراحته في حاضره ومستقبله."},{"h":"اختلاف النظرة","x":"قد يظن المربي أنه متوازن، وينظر إليه بعضهم على أنه متشدد، وآخرون على أنه متساهل."}]},{"t":"نواة الأسرة رجل وامرأة","pg":63,"key":"إذن الأم والأب يقومان بإيجاد التكامل في تربية الأبناء من خلال اختلاف طبيعتهما وأدوارهما، وفي التكامل توازن واعتدال","p":[],"items":[{"h":"صور التكامل","x":"أب حازم وأم شفيعة، أم تسر بالتفاصيل وأب يتحدث في الأساسيات، أم تحذر من العواقب وأب يميل إلى العملية والتفاؤل."},{"h":"التنسيق ضروري","x":"التكامل لا يتم تلقائياً، فعدم التنسيق قد يؤدي إلى الصدام والنزاع."}]},{"t":"التوازن في القرارات داخل الأسرة","pg":64,"key":"الموقف المتوازن لا يتجسد في الاستعجال، ولا في التسويف، ولكن في دراسة الطلب على نحو جاد على انفراد، أو مع الأسرة","p":[],"items":[{"h":"طرف التسويف","x":"آباء يقابلون طلبات الأبناء دائماً بالتأجيل: إن شاء الله سيكون هذا قريباً، ثم لا يحدث شيء."},{"h":"طرف الإسراع","x":"آباء يسارعون إلى تلبية كل طلب، فيفتحون شهية الأبناء على مزيد من الطلبات."},{"h":"الوفاء بالوعد","x":"المهم ألا يشعر الأولاد بإهمال أبويهم لطلباتهم، وأن يجدوا الوفاء بالوعد الذي سمعوه."}]},{"t":"التوازن بين الحرية والضبط","pg":64,"key":"أن الشيء إذا تجاوز حده انقلب إلى ضده","p":["إننا ضد التسلط على الأبناء، وضد تحويلهم إلى دمى وإمَّعات، ومجرد أشخاص تابعين، فهذا يُلحق بهم أفدح الأضرار النفسية"],"items":[{"h":"الحرية الزائدة","x":"الأطفال الذين يتمتعون بقدر كبير من حرية التصرف يكونون غير سعداء، ولا يعرفون قيمة أي شيء."},{"h":"مهمتنا الأساسية","x":"ليست ترفيه الأبناء، وإنما إعدادهم للحياة والتعامل الجيد مع الناس، وقبل ذلك أن يكونوا من الصالحين."},{"h":"التدرج مع العمر","x":"ضبط وسيطرة في الصغر، ثم تخفيف في المراهقة، ثم معاملة الأصدقاء في الجامعة مع دور المرشد الناصح."}]},{"t":"التوازن في عملية دمج الطفل في المجتمع","pg":66,"key":"علينا أن ننظر إلى الاختلاف بيننا وبين أبنائنا على أنه هو الأصل، وعلينا ألا نقع في خطأ طلب التطابق","p":["إن المرء لن يجد الحافز لبذل الجهد في تخصص أُكره عليه إكراهاً، ولن يبدع في تخصص لا يحبه"],"items":[{"h":"حرية الطفل أصل","x":"التدخل في شؤونه خلاف الأصل، فإذا فرضنا شيئاً نترك له مساحة للخيار، كاللباس الساتر مع حرية الألوان والطراز."},{"h":"الطبع الشاذ","x":"إن كان للطفل مزاج صعب نراعي طبيعته قدر الإمكان مع مطالبته بالحد الأدنى من التكيف."},{"h":"اختيار التخصص","x":"نلاحظ ميول الطفل ونهيئ له دراسة ما يحب، ونوضح له حاجات سوق العمل، والقرار له في النهاية."}]}],"quiz":[{"q":"كيف يصف المؤلف الفضيلة في مجال الأخلاق والعادات؟","o":["وسط بين رذيلتين، ولكل طرف منهما حد","طرف أعلى يسعى إليه المربي دائماً","اتباع ما تعارف عليه المجتمع من عادات","مقدار ثابت لا يختلف من طفل إلى آخر"],"why":"نحن نعرف في مجال الأخلاق والعادات أن الفضيلة وسط بين رذيلتين، أي أن الفضيلة لها طرفان","pg":61},{"q":"طلب ابنك الانتقال إلى مدرسة يراها أفضل، فما الموقف المتوازن عند المؤلف؟","o":["دراسة الطلب بجد ثم جواب واضح في موعد محدد","الموافقة الفورية حتى لا يشعر بالإهمال","التأجيل بقولك: إن شاء الله سيكون هذا قريباً","الرفض لأن الاستجابة تفتح شهية الطلبات"],"why":"ولكن في دراسة الطلب على نحو جاد على انفراد، أو مع الأسرة، ولا بأس في أن يكون الجواب: بعد شهر من الآن ستسمعون ما الذي سنفعله.","pg":64},{"q":"ماذا تبين من الدراسات عن الأطفال الذين يتمتعون بقدر كبير من حرية التصرف؟","o":["أنهم غير سعداء ولا يقدرون قيمة الأشياء","أنهم أكثر إبداعاً وثقة بأنفسهم من غيرهم","أنهم أقدر على تحمل الشدائد حين يكبرون","أنهم أكثر تفوقاً في دراستهم الجامعية"],"why":"حيث تبين أن الأطفال الذين يتمتعون بقدر كبير من حرية التصرف يكونون غير سعداء؛ لأنهم لا يقدِّرون، ولا يعرفون قيمة أي شيء","pg":65},{"q":"كيف تتدرج سلطة الأبوين مع نمو الأبناء كما يرسمها المؤلف؟","o":["تخف كلما كبروا حتى يعاملوا في الجامعة كأصدقاء","تشتد في المراهقة لأنها أخطر مراحل العمر","تبقى ثابتة لأن الطفل يحتاج إلى الضبط في كل مراحله","تبدأ خفيفة في الصغر ثم تزداد مع الكبر"],"why":"فإذا دخلوا في مرحلة المراهقة: خففنا سلطتنا وسيطرتنا أكثر فأكثر، فإذا دخلوا الجامعة: صرنا نعاملهم في معظم الأحيان على أنهم أصدقاء أعزاء","pg":66},{"q":"ما رأي المؤلف في إلزام الابن بدراسة تخصص لا يحبه؟","o":["لن يجد الحافز لبذل الجهد ولن يبدع فيه","مقبول إذا كان التخصص مطلوباً في سوق العمل","صحيح لأن الأهل أعرف بمصلحة أبنائهم","لا بأس به إذا كان التخصص مرموقاً جداً"],"why":"إن المرء لن يجد الحافز لبذل الجهد في تخصص أُكره عليه إكراهاً، ولن يبدع في تخصص لا يحبه","pg":69}],"scene":{"t":"اختيار الملابس","x":"ابنك يريد أن يختار ألوان ملابسه وطرازها بنفسه، وذوقه يخالف ذوقك، والأمر في دائرة المباح.","opts":["تشترط أن يكون اللباس ساتراً ثم تترك له اختيار الألوان والطراز","تختار له ملابسه كلها لأنه لا يحسن الاختيار بعد","تترك له الحرية الكاملة دون أي شرط"],"why":"فحين نقول للصبي أو البنت: إن اللباس ينبغي أن يكون ساتراً لكذا وكذا، فإننا لا نتدخل بعد ذلك في الألوان وطراز الثوب","pg":67}},{"k":"c8","t":"القاعدة الثامنة: التربية تعاطف","q":"كيف يشعر الطفل بأن كل ما نفعله معه نابع من الحب؟","essence":"المشاركة في المشاعر والتشجيع يبنيان الثقة","kw":["التعاطف","المشاعر","المكافأة"],"sections":[{"t":"التربية تعاطف، والمشاركة في المشاعر","pg":71,"key":"هو أن جميع ما نقوم به أثناء تربيتهم يصب بصورة من الصور في مصلحتهم، وهذا الشيء لن يكون سوى العطف والتعاطف، والتشجيع والاهتمام، والرحمة والشفقة.","p":["إن مشاركة الطفل في مشاعره، والتعاطف معه من خلال إظهار الفرحة لفرحه، وإظهار الحزن لحزنه، سوف تشجعه على أن يفضي بمشاعره إلينا"],"items":[{"h":"مخاوف الصغار","x":"كلما صغر سن الطفل كثرت الأشياء التي يخاف منها، فيصبح تعاطف الآباء مورداً مهماً لشعوره بالأمان."},{"h":"مشاعر غير منطقية","x":"طفل يبكي على لعبة رخيصة، والمطلوب فهم مشاعره ومراعاتها بقطع النظر عن منطقيتها."},{"h":"بعد الإخفاق","x":"من لم ينجح في اختبار لا يفيده التوبيخ، بل نتفهم إحباطه ونقول: ندرك أنك بذلت جهدك."}]},{"t":"نعم... ولكن","pg":73,"key":"يتطلب (التعاطف) من المربي الإكثار من كلمة (نعم)، وجعلها هي الأساس في الإجابة على طلبات الطفل","p":["ويمكن الحل أن نقول في معظم الأحيان: «نعم... ولكن ليس الآن»"],"items":[{"h":"الإحراج","x":"لا نستطيع الموافقة على كل الطلبات، ولا نريد أن نترك انطباعاً بأننا غير مستعدين لإسعادهم."},{"h":"صيغ مشروطة","x":"نعم، ولكن بشرط أن تحفظ جزءاً من القرآن، نعم، ولكن حين تدخر ما يكفي من المال."}]},{"t":"التعاطف موقف وسلوك","pg":74,"key":"إن التعاطف في حاجة إلى أن يتجسد في سلوكنا وتعاملنا مع أبنائنا، التعاطف مشاعر جميلة يولّدها الفعل، ويمنحها المصداقية والرسوخ","p":[],"items":[{"h":"الضحك والذكريات","x":"التجاوب مع الطرف التي يلقيها الأبناء، والتفاعل معهم وهم يسردون ذكرياتهم."},{"h":"الجانب الفكري","x":"الاستماع إلى آراء الأبناء وأفكارهم ومقترحاتهم ومناقشتهم، فهذا يزيد من تماسك الأسرة."},{"h":"البعد الروحي","x":"الأب ممسك بيد ولده إلى المسجد، والأسرة تتلو القرآن وتدعو الله معاً."}]},{"t":"المكافأة والتشجيع","pg":76,"key":"تدل الدراسات والتجارب على أن المكافأة التي نقدمها للطفل ينبغي أن تكون عقب قيامه بالعمل الممدوح مباشرة","p":["تشير بحوث وإحصاءات عديدة إلى أن المكافآت المعنوية أعظم تأثيراً في نفس الطفل من المكافآت المادية","إن التعاطف والاهتمام والتشجيع وتقديم المكافآت المختلفة من الأمور التي لا يبالي بها كثير من الناس بسبب عدم إدراكهم لأهميتها"],"items":[{"h":"مقياس التحضر","x":"التشجيع يشكل مقياساً من مقاييس التحضر، فالمجتمعات كلما تحضرت قدرت المواهب أكثر."},{"h":"الحب قبل المال","x":"امنح أبناءك الكثير من الحب، والقليل من المال."},{"h":"لا مكافأة على الواجب","x":"إذا اشترط الطفل مكافأة على أعماله المطلوبة منه فلا يصح تقديمها، بل عليه أن ينجز مهامه دون مقابل."},{"h":"لا تعزيز للخطأ","x":"من المهم ألا نستخدم المكافأة في تعزيز السلوك الخاطئ من حيث لا نشعر."}]}],"quiz":[{"q":"ما المفهوم المهم الذي نريد غرسه في نفوس الأبناء عبر دفء العلاقة معهم؟","o":["أن كل ما نقوم به في تربيتهم يصب في مصلحتهم","أن الأبوين لا يخطئان أبداً في قراراتهما","أن المكافأة المالية هي أصدق دليل على محبتنا لهم","أن الطاعة التامة شرط لنيل محبة الأبوين"],"why":"هو أن جميع ما نقوم به أثناء تربيتهم يصب بصورة من الصور في مصلحتهم","pg":71},{"q":"عاد ابنك من المدرسة بدرجة متدنية وهو يبكي لأنه كان يتوقع النجاح، فماذا تفعل؟","o":["تتفهم إحباطه وتطمئنه بأنك تقدّر جهده","توبخه ليعرف أن عاقبة الإهمال هي الفشل","تعرض عنه وتتركه يعايش أحزانه وحده","تقارنه بزملائه الأوائل ليجتهد أكثر"],"why":"نحن ندرك أنك قد بذلت جهدك، وأن الامتحان كان أصعب مما توقعت، ولا يجب أن تفكر كثيراً في هذا الأمر","pg":73},{"q":"ماذا يقصد المؤلف بقاعدة: نعم... ولكن؟","o":["أن تكون الموافقة هي الأصل مع ربطها بشرط","أن نرفض الطلب بلطف وهدوء حتى لا يغضب الطفل","أن نوافق على كل الطلبات دون أي شرط","أن نؤجل الإجابة حتى ينسى الطفل طلبه"],"why":"يتطلب (التعاطف) من المربي الإكثار من كلمة (نعم)، وجعلها هي الأساس في الإجابة على طلبات الطفل","pg":73},{"q":"أي المكافآت أعظم تأثيراً في نفس الطفل بحسب البحوث التي يذكرها المؤلف؟","o":["المعنوية كالابتسامة والتقبيل والمعانقة","المادية كالنقود والحلوى والهدايا الثمينة","المؤجلة إلى نهاية العام الدراسي","الكبيرة مهما تأخر موعد تقديمها"],"why":"تشير بحوث وإحصاءات عديدة إلى أن المكافآت المعنوية أعظم تأثيراً في نفس الطفل من المكافآت المادية","pg":77},{"q":"طفلة تصر على النوم مع أبويها فتعطيها أمها قطعة حلوى كي تنام وحدها، ما رأي المؤلف؟","o":["هذا يربط عندها بين الإصرار والحصول على الحلوى","هذا تشجيع صحيح لأنه جاء عقب السلوك المطلوب مباشرة","هذا مقبول لأن الحلوى مكافأة مادية بسيطة","هذا أنفع من المكافأة المعنوية في مثل سنها"],"why":"إن هذا التصرف من الأم يجعل الطفل يربط بين الإصرار على النوم مع والديه، وبين الحصول على الحلوى","pg":78}],"scene":{"t":"لعبة مفقودة","x":"فقد ابنك الصغير لعبة رخيصة الثمن، فأخذ يبكي بكاءً مراً.","opts":["تحاول فهم مشاعره وتراعيها ولو بدت لك غير منطقية","تقول له: إنها لعبة رخيصة لا تستحق كل هذا البكاء","تتجاهل بكاءه حتى يهدأ وحده"],"why":"فإن المطلوب من الآباء محاولة فهم حقيقة المشاعر التي تتحرك في نفس الطفل، والتجاوب معها، ومراعاتها بقطع النظر عن نظرتهم لمنطقية تلك المشاعر وواقعيتها","pg":72}},{"k":"c9","t":"القاعدة التاسعة: تفهم أسباب مشكلاتهم","q":"لماذا يجب أن نفهم أسباب مشكلات الأبناء قبل علاجها؟","essence":"فهم السبب نصف العلاج","kw":["النشاط الزائد","الكذب","الغيرة بين الإخوة"],"sections":[{"t":"تفهم أسباب مشكلاتهم","pg":79,"key":"لكن النية الصادقة لا تكفي بمفردها للتعامل مع المشكلات، بل لا بد من تفهم طبيعة مشكلات الأبناء، وتفهم أسبابها وجذورها حتى تكون هناك إمكانية لمعالجتها.","p":["فالأشقاء والشقيقات عبارة عن مخطوطات فريدة، ولكل واحد منهم سماته وخصائصه الشخصية"],"items":[{"h":"لا نسخ مكررة","x":"كثير من الآباء يعتقدون أن أبناءهم نسخ مكررة، فإذا كان الكبير سوياً استنكروا مشكلة أخيه."},{"h":"التبكير","x":"مشكلات صغيرة حين يكون الأطفال صغاراً تكبر معهم إن لم تعالج مبكراً."},{"h":"استشارة المتخصص","x":"من لديه طفل غير طبيعي أو يعاني مشكلة عقلية أو حركية أو نفسية فعليه أن يتثقف ويستمع لنصائح الأطباء."}]},{"t":"النشاط الزائد","pg":80,"key":"إننا حين نعرف الأمور التي تسبب النشاط الزائد لدى أبنائنا؛ فإن المتوقع هو رحمة الطفل وإعذاره عوضاً عن لومه ومعاقبته.","p":[],"items":[{"h":"مظاهره","x":"حركة سريعة غير متزنة، وعدم القدرة على الجلوس إلا ثواني، وإزعاج الآخرين."},{"h":"أسبابه","x":"وراثة، أو خلل وظيفي في الدماغ، أو ضربات شديدة على الرأس، أو تسمم من أغذية، أو حالة الأم أثناء الحمل، أو مناكفة الأم للطفل ونقدها الشديد له."}]},{"t":"كذب الأطفال","pg":81,"key":"إن فهمنا للأسباب التي تدفع الطفل إلى قول غير الحقيقة يملي علينا أن نغير في أسلوب تعاملنا معه","p":["إن الطفل في مرحلة ما قبل المدرسة يكذب؛ لأنه يجد صعوبة في التفريق بين الحقيقة والخيال"],"items":[{"h":"دوافع الكذب","x":"الحصول على مكسب شخصي، أو حماية صديق، أو تقليد الكبار، أو الدفاع عن النفس خوف العقوبة، أو كسب إعجاب الزملاء، أو العدوانية، أو التخلص من ذكريات مؤلمة."},{"h":"الوصمة","x":"إذا أكثر الأبوان من وصف الطفل بأنه كذاب صارت الوصمة جزءاً من صورته الذهنية عن نفسه."},{"h":"سحب الثقة","x":"قد ندفع الصغار إلى الكذب حين نسحب ثقتنا منهم، فيخترع الطفل الكلام الذي يظن أنه يلقى قبولاً."}]},{"t":"مشاكسات الأشقاء","pg":83,"key":"إن الأطفال يتسابقون على الاستحواذ على محبة أبويهم لهم، فإذا شعروا أن واحداً منهم فاز بذلك دونهم أضمروا له العداوة والكراهية","p":["والحقيقة: أن المناكفات والمشاكسات بين الأبناء هي شيء طبيعي جداً، إلا إذا تجاوزت المألوف"],"items":[{"h":"تباين الأمزجة","x":"الأطفال ولو كانوا أشقاء لا تتطابق أمزجتهم وأذواقهم، والاحتكاك اليومي على الأشياء يثير الخلافات."},{"h":"التفضيل","x":"إشادة الأبوين بالذكي والوسيم من أبنائهم تؤجج العداوة، كما في قصة إخوة يوسف."},{"h":"المقارنة","x":"مقارنة البنت بأختها المنظمة تجعل صدرها يغلي بالحقد على أختها."},{"h":"سلطة الأكبر","x":"منح الأخ الأكبر سلطات واسعة على إخوته يولد العداوات، فالأوسط ينتقم من الأصغر."}]}],"quiz":[{"q":"ما الذي لا يكفي وحده في التعامل مع مشكلات الأبناء بحسب المؤلف؟","o":["النية الصادقة دون فهم أسباب المشكلات","قراءة الكتب المتخصصة في شؤون التربية","استشارة الأطباء والمتخصصين في الحالة","ملاحظة تكرار السلوك لدى الطفل ومتابعته"],"why":"لكن النية الصادقة لا تكفي بمفردها للتعامل مع المشكلات، بل لا بد من تفهم طبيعة مشكلات الأبناء، وتفهم أسبابها وجذورها","pg":79},{"q":"ما المتوقع من الأهل حين يعرفون أسباب النشاط الزائد لدى طفلهم؟","o":["رحمة الطفل وإعذاره بدلاً من لومه ومعاقبته","منعه من زيارة الأقارب والجيران حتى يهدأ","نقده بشدة حتى يتعلم كيف يضبط حركته","تكليفه بأعمال كثيرة شاقة تستنفد طاقته"],"why":"إننا حين نعرف الأمور التي تسبب النشاط الزائد لدى أبنائنا؛ فإن المتوقع هو رحمة الطفل وإعذاره عوضاً عن لومه ومعاقبته.","pg":81},{"q":"لماذا يكذب الطفل في مرحلة ما قبل المدرسة كما يقرر المؤلف؟","o":["لصعوبة التمييز عنده بين الحقيقة والخيال","لرغبته في خداع الكبار وتضليلهم عن عمد وقصد","لخوفه الدائم من عقوبة والديه الشديدة","لتأثره برفاق السوء في الحي والمدرسة"],"why":"إن الطفل في مرحلة ما قبل المدرسة يكذب؛ لأنه يجد صعوبة في التفريق بين الحقيقة والخيال","pg":81},{"q":"ما أثر الإكثار من وصف الطفل بأنه كذاب في نظر المؤلف؟","o":["تصير الوصمة جزءاً من صورته عن نفسه فيكذب","يخجل الطفل من الكذب فيتركه بعد وقت قصير جداً","يتعلم الطفل الاعتذار عن كل خطأ يرتكبه","يصبح الطفل أكثر حذراً في اختيار رفاقه"],"why":"فإن هذه الوصمة تصبح جزءاً من الصورة الذهنية لديه عن نفسه، أي أنه يصبح مقتنعاً تمام الاقتناع بأنه شخص كذاب، فيندفع إلى الكذب من غير شعور منه.","pg":83},{"q":"قالت أم لابنتها: أود أن تتعلمي من أختك فلانة. ما أثر ذلك كما يذكر المؤلف؟","o":["يغلي صدر البنت بالحقد على أختها","تتحمس البنت لتقليد أختها في النظام","يزداد قرب الأختين وتعاونهما معاً","تشعر البنت بأن أمها تهتم بشأنها"],"why":"إن هذا سيجعل صدر البنت المتهمة بالفوضى يغلي بالحقد على أختها الأخرى","pg":85}],"scene":{"t":"من فعلها؟","x":"وجدت شيئاً مكسوراً في البيت، فسألت الأبناء فأنكروا جميعاً، وأنت تعرف أن أحدهم فعلها.","opts":["تبحث عن دافع الإنكار كالخوف من العقوبة، وتغير أسلوب تعاملك","تصف من تشك فيه بأنه كذاب أمام إخوته","تعاقبهم جميعاً حتى يعترف الفاعل"],"why":"إن فهمنا للأسباب التي تدفع الطفل إلى قول غير الحقيقة يملي علينا أن نغير في أسلوب تعاملنا معه","pg":83}},{"k":"c10","t":"القاعدة العاشرة: لا تربية من غير تأديب","q":"كيف نؤدب الأبناء بحزم دون قسوة ولا إهانة؟","essence":"تأديب حازم واضح قصير بلا ضرب","kw":["التأديب","النتائج المنطقية","الحزم"],"sections":[{"t":"لا تربية من غير تأديب، والتأديب جهد تكميلي","pg":87,"key":"القاعدة العامة في هذا: إن المزيد من الجهد التربوي الإيجابي سوف يقلل من الحاجة إلى التأديب، والعكس صحيح.","p":["الطفل لا يملك معايير الصواب والخطأ، ولا يعرف اللائق والمناسب من غير اللائق وغير المناسب","العقوبات لا تنشئ طفلاً، ولا دولة، ولا مجتمعاً، لكنها تحمي الطفل والدولة والمجتمع"],"items":[{"h":"اختلاف الطباع","x":"في الأطفال المسالم المطواع والمشاغب العنيد، فاحتياجهم إلى التأديب ليس على درجة واحدة."},{"h":"الخطأ المعاكس","x":"بعض الآباء يلوذون بالصمت ويتجاهلون الأخطاء، ثم يثورون ويوقعون أشد العقوبات."}]},{"t":"التخطيط للتأديب","pg":88,"key":"يحتاج تأديب الأطفال إلى تخطيط وإلى رؤية حتى يكون فعالاً ومجدياً","p":[],"items":[{"h":"اتفاق الأبوين","x":"البداية اتفاق الأبوين على أشكال العقوبات، لأن اختلافهما قد يفسد العملية كلها."},{"h":"اجتماعات مع الأبناء","x":"توضيح المطلوب منهم في البيت وخارجه، والاتفاق معهم على جزاء من يخالف."}]},{"t":"تأديب حازم من غير إهانة","pg":89,"key":"التأديب الصحيح هو التأديب الذي يحمل رسالة واضحة بالخطأ الذي ارتكبه الطفل، وبضرورة عدم تكراره في المستقبل","p":["لأن العلاقة الدافئة هي الحبل السري الذي يتغذى منه الطفل، وينبغي المحافظة عليها بكل وسيلة","إن تطبيق النظام والعقوبات ينبغي أن يتم بأسلوب عملي وصامت وجاد من غير صياح، ولا تهديد، ولا تحذير، ولا مقدمات."],"items":[{"h":"التنفيذ دون تسويف","x":"التطبيق الحرفي للعقوبة يجعل الأطفال يتنبؤون بنتائج أعمالهم، وهذا التنبؤ يردعهم."},{"h":"مثال التلفاز","x":"أبوان حذرا من تجاوز الساعة، ثم نفذا المنع ثلاثة أشهر، فصار الأطفال يحاسبون أنفسهم بالدقيقة."},{"h":"الحزم ليس قسوة","x":"الحرمان شهراً كاملاً أو الألفاظ النابية أو الضرب على الوجه إهانة وقسوة لا تعد من الأساليب الناجعة."}]},{"t":"حد أدنى من التهذيب، وتحمل النتائج المنطقية","pg":91,"key":"من المهم أن نجعل الأطفال يوقنون أنهم حين يسلكون سلوكاً معيناً؛ فإن عليهم أن يتحملوا النتائج المنطقية التي تترتب عليه","p":[],"items":[{"h":"عتبة الأدب","x":"لا يصح أن يدخل الولد على أبويه دون سلام، أو يخرج دون استئذان، أو يرفع صوته عليهما."},{"h":"مائدة الغداء","x":"ولد تأخر عن الغداء بمكالمة هاتفية فرفعت المائدة، فلم يجد طعاماً، فتعلم الحذر من التأخر."},{"h":"ثياب الروضة","x":"طفل رفض ارتداء ثيابه، فوضعها أبوه في كيس وأوصله بثياب النوم، فانتهت مشكلة الزعل اليومي."}]},{"t":"لكل مرحلة عمرية تأديب يناسبها","pg":92,"key":"حين يكون الطفل في الثالثة؛ فإنك لا تستطيع عقد اتفاقية معه حول السلوك الذي ينبغي عليه أن يسلكه","p":[],"items":[{"h":"ابن الثالثة","x":"العبوس في وجهه حين يخطئ يوصل إليه رسالة، وحجب الحب عنه يشكل وسيلة تأديبية رادعة."},{"h":"ابن الثالثة عشرة","x":"يشعر بالاستقلالية، فحجب التعاطف لا يؤثر فيه، ومنعه من بعض ما يحب هو المؤثر، كمنع الهاتف."}]},{"t":"عقوبة محددة، ولا للضرب","pg":93,"key":"أنا أنظر إلى العقوبة في سياق التربية على أنها أشبه شيء ب(تحويلة) نخرج فيها عن الطريق لنعود إليه بعد انتهائها، وكلما كانت التحويلة أقصر وأوضح كان ذلك أفضل.","p":["علينا أن ننظر إلى الضرب في مسألة التأديب على أنه الشيء الذي لا يصح أن نفكر فيه، لا من بعيد ولا من قريب"],"items":[{"h":"لا للتوبيخ المستمر","x":"لا للعقوبات المبهمة، ولا للتأنيب المتواصل، ولا لفتح الدفاتر القديمة، فهذا كله يضر ولا ينفع."},{"h":"القدوة النبوية","x":"يذكر المؤلف حديث عائشة رضي الله عنها: «ما ضرب رسول الله ﷺ خادماً ولا امرأة قط»."},{"h":"إن وقع الأمر","x":"يحذر المؤلف أشد الحذر من الضرب على الوجه، وأمام الناس، والضرب المؤلم، وألا يلجأ إليه المربي وهو غاضب."}]}],"quiz":[{"q":"ما القاعدة العامة في العلاقة بين الجهد التربوي الإيجابي والتأديب؟","o":["كلما زاد الجهد الإيجابي قلت الحاجة إلى التأديب","كلما زاد التأديب قلت الحاجة إلى الجهد الإيجابي","التأديب هو الأصل والجهد الإيجابي مكمل له","لا صلة بين الجهد الإيجابي والحاجة إلى التأديب أصلاً"],"why":"القاعدة العامة في هذا: إن المزيد من الجهد التربوي الإيجابي سوف يقلل من الحاجة إلى التأديب، والعكس صحيح.","pg":88},{"q":"ما صفة التأديب الصحيح كما يحددها المؤلف؟","o":["يحمل رسالة واضحة بالخطأ وبضرورة عدم تكراره","يكون شديداً مؤلماً حتى لا ينسى الطفل عقوبته أبداً","يقع أمام الإخوة جميعاً ليعتبروا بما حدث","يؤخر حتى يهدأ غضب الأبوين تماماً ثم ينسى"],"why":"التأديب الصحيح هو التأديب الذي يحمل رسالة واضحة بالخطأ الذي ارتكبه الطفل، وبضرورة عدم تكراره في المستقبل","pg":89},{"q":"بأي أسلوب ينبغي أن تطبق العقوبات في البيت عند المؤلف؟","o":["بأسلوب عملي صامت جاد، بلا صياح ولا تهديد","بصوت مرتفع حتى يدرك الطفل حجم خطئه","بعد إنذارات متكررة ومقدمات طويلة","بحسب حالة المربي ومزاجه في ذلك اليوم بعينه"],"why":"إن تطبيق النظام والعقوبات ينبغي أن يتم بأسلوب عملي وصامت وجاد من غير صياح، ولا تهديد، ولا تحذير، ولا مقدمات.","pg":90},{"q":"طفل في الثالثة يهم بعمل خاطئ، فما الأنسب في تأديبه بحسب المؤلف؟","o":["العبوس في وجهه أو الإعراض عنه قليلاً","عقد اتفاقية معه حول السلوك المطلوب","حرمانه من مصروفه طوال شهر كامل","منعه من الهاتف والخروج مع رفاقه في الحي"],"why":"فإن العبوس في وجهه حين يقع في عمل خاطئ، أو حين يريد الإقدام عليه يوصل رسالة أو معنى إليه","pg":92},{"q":"كيف ينظر المؤلف إلى العقوبة في سياق التربية؟","o":["تحويلة نخرج فيها عن الطريق ثم نعود إليه","طريق ثابت نسلكه مع كل خطأ مهما صغر","وسيلة لإظهار هيبة الأب وسلطته أمام أسرته","حساب شامل نفتح فيه الدفاتر القديمة"],"why":"أنا أنظر إلى العقوبة في سياق التربية على أنها أشبه شيء ب(تحويلة) نخرج فيها عن الطريق لنعود إليه بعد انتهائها","pg":93}],"scene":{"t":"تأخر عن الغداء","x":"نادت الأسرة الأولاد إلى الغداء، فتأخر أحدهم بمكالمة هاتفية مع صديقه رغم أنه يعرف موعد رفع المائدة.","opts":["ترفع المائدة في موعدها فيتحمل نتيجة تأخره","تحتفظ له بطعامه حتى لا يبقى جائعاً","تصرخ عليه وتأخذ هاتفه شهراً كاملاً"],"why":"من المهم أن نجعل الأطفال يوقنون أنهم حين يسلكون سلوكاً معيناً؛ فإن عليهم أن يتحملوا النتائج المنطقية التي تترتب عليه","pg":91}}],"highlights":[{"x":"الطفل أعقد من أي آلة، ويحتاج تربيته التربية الرشيدة إلى معرفة وخبرة وحذق","pg":7},{"x":"إصلاح الخلل الذي في حياتنا لن يتجه من الخارج إلى الداخل، وإنما من الداخل إلى الخارج.","pg":9},{"x":"إن التربية سهلة ومثمرة وناجحة إذا كنا نحن الكبار أشخاصاً جيدين","pg":26},{"x":"إن الأمة الفقيرة ليست هي التي لا تملك الكثير من المال","pg":28},{"x":"أن الشيء هبة علاقاته","pg":34},{"x":"اسأل وناقش وتابع، ولكن اترك له القرار","pg":48},{"x":"لا تربية من غير اهتمام.","pg":55},{"x":"أن الشيء إذا تجاوز حده انقلب إلى ضده","pg":65},{"x":"امنح أبناءك الكثير من الحب، والقليل من المال","pg":77},{"x":"العقوبات لا تنشئ طفلاً، ولا دولة، ولا مجتمعاً، لكنها تحمي الطفل والدولة والمجتمع","pg":88},{"x":"العلاقة الدافئة هي الحبل السري الذي يتغذى منه الطفل","pg":89}],"concepts":[{"term":"الثقافة التربوية","def":"مجموعة المعلومات والخبرات التي نحتاج إليها في تكوين البيئة التربوية، وفي طرق تهذيب الأبناء وتنشئتهم النشأة الصالحة، وفي التعامل مع مشكلاتهم وأخطائهم.","pg":8},{"term":"قانون السلم القيمي","def":"فإنه تتم التضحية بالقيمة الأقل شأناً من أجل الحفاظ على القيمة الأعظم شأناً.","pg":20},{"term":"بيئة الأسرة","def":"تتكون بيئة الأسرة من العديد من العناصر، أهمها: شخصيات أفراد الأسرة، والقيم التي يحملونها، ونوعية العلاقات القائمة بينهم","pg":23},{"term":"التفاعل التربوي","def":"إن التربية ليست عبارة عن استجابات تصدر من الأطفال لتوجيهات آبائهم أو وصاياهم، وإنما هي عمل في اتجاهين","pg":34},{"term":"الوضوح","def":"يشكل واحدة من أكبر فضائل الحياة؛ لأنه يتصل بالبصر والبصيرة، والعلم والنور، والوعي والفهم","pg":41},{"term":"الشجاعة الأدبية","def":"وهو يعني قول الحق والدفاع عنه، والصراحة في إبداء الملاحظات على ما يجري حول الطفل","pg":51},{"term":"جيل التلفاز","def":"جيل لا يرى من الفضائيات إلا القليل من الدعوة إلى المثل العليا والأخلاق الحميدة","pg":56},{"term":"القرب من الأبناء","def":"بناء علاقة ثقة ومودة معهم","pg":58},{"term":"الوسط","def":"وإنما كان الوسط محموداً؛ لأنه مجانب للغلو والتقصير","pg":61},{"term":"التعاطف","def":"التعاطف مشاعر جميلة يولّدها الفعل، ويمنحها المصداقية والرسوخ","pg":74},{"term":"المكافآت المعنوية","def":"المكافآت المعنوية تكون في الابتسامة والتقبيل والمعانقة والربت على الكتف، ومسح الرأس","pg":77},{"term":"الكذب","def":"أن يقول الإنسان شيئاً يخالف ما يعتقده","pg":81},{"term":"التأديب الصحيح","def":"التأديب الذي يحمل رسالة واضحة بالخطأ الذي ارتكبه الطفل، وبضرورة عدم تكراره في المستقبل","pg":89},{"term":"النتائج المنطقية","def":"أنهم حين يسلكون سلوكاً معيناً؛ فإن عليهم أن يتحملوا النتائج المنطقية التي تترتب عليه","pg":91}],"links":[{"topic":"القدوة","pg":26},{"topic":"العولمة والتربية","pg":17},{"topic":"الحوار مع الأبناء","pg":35},{"topic":"التلفاز والشاشات","pg":39},{"topic":"المراهقة","pg":59},{"topic":"المكافأة والتشجيع","pg":76},{"topic":"الكذب","pg":81},{"topic":"الغيرة بين الإخوة","pg":84},{"topic":"العقوبة","pg":93},{"topic":"الضرب","pg":93}]};
